def drill_into_january_order_activity(inventory):
    """
    Drill into January order activity for out-of-stock products.

    Args:
    inventory (dict): Inventory data.

    Returns:
    None
    """
    if check_out_of_stock(inventory):
        # Assuming the order activity is stored in a separate data structure
        order_activity = {
            "period": {
                "start_date": "2026-01-01",
                "end_date": "2026-01-31"
            },
            "orders": [
                {
                    "order_id": 1,
                    "product_id": 4,
                    "quantity": 2,
                    "order_date": "2026-01-05"
                },
                {
                    "order_id": 2,
                    "product_id": 1,
                    "quantity": 1,
                    "order_date": "2026-01-10"
                }
            ]
        }

        print("Out-of-stock products in January:")
        for item in inventory["inventory"]["low_stock_items"]:
            print(f"Product ID: {item['product_id']}, Product Name: {item['product_name']}")
            print("January Order Activity:")
            for order in order_activity["orders"]:
                if order["product_id"] == item["product_id"]:
                    print(f"Order ID: {order['order_id']}, Quantity: {order['quantity']}, Order Date: {order['order_date']}")
            print()
    else:
        print("No out-of-stock products in January.")

